/* ===========================================================
   promoStarburst — logo « étoile PROMO » réutilisable, clignotant
   et changeant de couleur en boucle (voir .promo-starburst-badge
   dans style.css). Utilisé sur le carrousel d'accueil et la page
   Catégories, partout où un univers a au moins un article en promo.
   =========================================================== */
function promoStarburst() {
  return `<svg viewBox="0 0 100 100" class="promo-starburst-svg">
    <polygon class="promo-starburst-star" points="50,2 57.76,21.02 74,8.43 71.21,28.79 91.57,26 78.98,42.24 98,50 78.98,57.76 91.57,74 71.21,71.21 74,91.57 57.76,78.98 50,98 42.24,78.98 26,91.57 28.79,71.21 8.43,74 21.02,57.76 2,50 21.02,42.24 8.43,26 28.79,28.79 26,8.43 42.24,21.02"/>
    <text x="50" y="57" text-anchor="middle" class="promo-starburst-text">PROMO</text>
  </svg>`;
}